                result[self.evaluate(key_node, scope)] = self.evaluate(value_node, scope)
        return result

    def _eval_Subscript(self, node: ast.Subscript, scope: dict[str, Any]) -> Any:
        return self.evaluate(node.value, scope)[self.evaluate(node.slice, scope)]

    def _eval_Slice(self, node: ast.Slice, scope: dict[str, Any]) -> slice:
        return slice(
            None if node.lower is None else self.evaluate(node.lower, scope),
            None if node.upper is None else self.evaluate(node.upper, scope),
            None if node.step is None else self.evaluate(node.step, scope),
        )

    def _eval_IfExp(self, node: ast.IfExp, scope: dict[str, Any]) -> Any:
        if self.evaluate(node.test, scope):
            return self.evaluate(node.body, scope)
        return self.evaluate(node.orelse, scope)

    def _eval_BoolOp(self, node: ast.BoolOp, scope: dict[str, Any]) -> Any:
        wants_truthy = isinstance(node.op, ast.Or)
        result: Any = None
        for value_node in node.values:
            result = self.evaluate(value_node, scope)
            if bool(result) is wants_truthy:
                return result
        return result

    def _eval_UnaryOp(self, node: ast.UnaryOp, scope: dict[str, Any]) -> Any:
        value = self.evaluate(node.operand, scope)
        if isinstance(node.op, ast.Not):
            return not value
        operation = UNARY_OPERATORS.get(type(node.op))
        if operation is None:
            raise ConfigExpressionError(
                f"{type(node.op).__name__} is not allowed in a configuration expression"
            )
        return self._guard_int(operation(value), "unary arithmetic")

    def _eval_BinOp(self, node: ast.BinOp, scope: dict[str, Any]) -> Any:
        left = self.evaluate(node.left, scope)
        right = self.evaluate(node.right, scope)
        operator_type = type(node.op)
        if operator_type is ast.Pow:
            return self._power(left, right)
        if operator_type in (ast.LShift, ast.RShift):
            return self._shift(operator_type, left, right)
        if operator_type is ast.Mult:
            self._guard_repeat(left, right)
        operation = BINARY_OPERATORS.get(operator_type)
        if operation is None:
            raise ConfigExpressionError(
                f"{operator_type.__name__} is not allowed in a configuration expression"
            )
        return self._guard_int(operation(left, right), "arithmetic")

    def _eval_Compare(self, node: ast.Compare, scope: dict[str, Any]) -> bool:
        left = self.evaluate(node.left, scope)
        for operator_node, comparator in zip(node.ops, node.comparators):
            right = self.evaluate(comparator, scope)
            operation = COMPARISONS.get(type(operator_node))
            if operation is None:
                raise ConfigExpressionError(
                    f"{type(operator_node).__name__} is not allowed in a configuration expression"
                )
            if not operation(left, right):
                return False
            left = right
        return True

    def _eval_Call(self, node: ast.Call, scope: dict[str, Any]) -> Any:
        if not isinstance(node.func, ast.Name):
            raise ConfigExpressionError(
                "configuration profiles may only call the allow-listed helper functions"
            )
        function = self._eval_Name(node.func, scope)
        if not callable(function):
            raise ConfigExpressionError(f"{node.func.id} is not callable")
        keywords: dict[str, Any] = {}
        for keyword in node.keywords:
            if keyword.arg is None:
                keywords.update(self.evaluate(keyword.value, scope))
            else:
                keywords[keyword.arg] = self.evaluate(keyword.value, scope)
        return function(*self._expand(node.args, scope), **keywords)

    def _eval_JoinedStr(self, node: ast.JoinedStr, scope: dict[str, Any]) -> str:
        return "".join(self.evaluate(value, scope) for value in node.values)

    def _eval_FormattedValue(self, node: ast.FormattedValue, scope: dict[str, Any]) -> str:
        value = self.evaluate(node.value, scope)
        if node.conversion == ord("r"):
            value = repr(value)
        elif node.conversion == ord("s"):
            value = str(value)
        elif node.conversion == ord("a"):
            value = ascii(value)
        if node.format_spec is None:
            return value if isinstance(value, str) else str(value)
        return format(value, self.evaluate(node.format_spec, scope))

    def _eval_ListComp(self, node: ast.ListComp, scope: dict[str, Any]) -> list[Any]:
        return [self.evaluate(node.elt, inner) for inner in self._scopes(node.generators, scope)]

    def _eval_SetComp(self, node: ast.SetComp, scope: dict[str, Any]) -> set[Any]:
        return {self.evaluate(node.elt, inner) for inner in self._scopes(node.generators, scope)}

    def _eval_DictComp(self, node: ast.DictComp, scope: dict[str, Any]) -> dict[Any, Any]:
        return {
            self.evaluate(node.key, inner): self.evaluate(node.value, inner)
            for inner in self._scopes(node.generators, scope)
        }

    def _eval_GeneratorExp(self, node: ast.GeneratorExp, scope: dict[str, Any]) -> Iterator[Any]:
        return self._generate(node.elt, node.generators, scope)

    def _generate(
        self, elt: ast.expr, generators: list[ast.comprehension], scope: dict[str, Any]
    ) -> Iterator[Any]:
        for inner in self._scopes(generators, scope):
            yield self.evaluate(elt, inner)

    def _scopes(
        self,
        generators: list[ast.comprehension],
        scope: dict[str, Any],
        index: int = 0,
    ) -> Iterator[dict[str, Any]]:
        if index == len(generators):
            yield dict(scope)
            return
        generator = generators[index]
        if getattr(generator, "is_async", False):
            raise ConfigExpressionError(
                "asynchronous comprehensions are not allowed in a configuration expression"
            )
        for value in self.evaluate(generator.iter, dict(scope)):
            inner = dict(scope)
            self._bind(generator.target, value, inner)
            if all(self.evaluate(condition, inner) for condition in generator.ifs):
                yield from self._scopes(generators, inner, index + 1)

    def _bind(self, target: ast.expr, value: Any, scope: dict[str, Any]) -> None:
        if isinstance(target, ast.Name):
            scope[target.id] = value
            return
        if isinstance(target, (ast.Tuple, ast.List)):
            values = list(value)
            if len(values) != len(target.elts):
                raise ConfigExpressionError("comprehension target does not match its value")
            for element, item in zip(target.elts, values):
                self._bind(element, item, scope)
            return
        raise ConfigExpressionError(
            f"{type(target).__name__} is not allowed as a comprehension target"
        )

    def _expand(self, nodes: list[ast.expr], scope: dict[str, Any]) -> Iterator[Any]:
        for node in nodes:
            if isinstance(node, ast.Starred):
                yield from self.evaluate(node.value, scope)
            else:
                yield self.evaluate(node, scope)

    def _guard_int(self, value: Any, description: str) -> Any:
        if isinstance(value, int) and not isinstance(value, bool):
            if value.bit_length() > MAX_INT_BITS:
                raise ConfigExpressionError(f"{description} produced an unreasonably large integer")
        return value

    def _power(self, left: Any, right: Any) -> Any:
        if isinstance(left, int) and isinstance(right, int) and right > MAX_EXPONENT:
            raise ConfigExpressionError("exponent is too large for a configuration expression")
        return self._guard_int(left**right, "exponentiation")

    def _shift(self, operator_type: type, left: Any, right: Any) -> Any:
        if isinstance(right, int) and right > MAX_INT_BITS:
            raise ConfigExpressionError("shift is too large for a configuration expression")
        operation = operator.lshift if operator_type is ast.LShift else operator.rshift
        return self._guard_int(operation(left, right), "shift")

    def _guard_repeat(self, left: Any, right: Any) -> None:
        for value, count in ((left, right), (right, left)):
            if not isinstance(value, (str, bytes, list, tuple)) or isinstance(count, bool):
                continue
            if isinstance(count, int) and count > MAX_REPEAT:
                raise ConfigExpressionError("repetition is too large for a configuration expression")


