class RefusedExpressions(unittest.TestCase):
    def assert_refused(self, expression):
        with self.assertRaises(ConfigExpressionError):
            load_config(expression)

    def test_attribute_access_is_refused(self):
        self.assert_refused("().__class__.__bases__[0].__subclasses__()")
        self.assert_refused("make_config.__globals__")

    def test_builtin_names_are_refused(self):
        for expression in ("__import__('os').system('id')", "open('/etc/passwd')", "eval('1+1')"):
            with self.subTest(expression=expression):
                with self.assertRaises(DisallowedNameError):
                    load_config(expression)

    def test_lambda_and_calls_on_computed_values_are_refused(self):
        self.assert_refused("(lambda: 1)()")
        self.assert_refused("[len][0]('abc')")

    def test_resource_exhaustion_is_refused(self):
        for expression in ("9 ** 9 ** 9", "1 << (10 ** 9)", "'a' * (10 ** 9)"):
            with self.subTest(expression=expression):
                self.assert_refused(expression)

    def test_disallowed_name_is_also_a_value_error(self):
        self.assertTrue(issubclass(DisallowedNameError, ValueError))
        self.assertTrue(issubclass(DisallowedNameError, NameError))

    def test_malformed_expression_reports_syntax_error(self):
        with self.assertRaises(SyntaxError):
            load_config("{'settings':")


if __name__ == "__main__":
    unittest.main()
